mapper.sql:
with nwchg as (
  select proc_cd
    from msf_request
   where cret_dt >= to_date(to_char(now(), 'YYYYMMDD'), 'YYYYMMDD')
     and cret_id = #{value}
), svchg as (
  select proc_cd
    from msf_request_svc_chg
   where cret_dt >= to_date(to_char(now(), 'YYYYMMDD'), 'YYYYMMDD')
     and cret_id = #{value}
), nmchg as (
  select proc_cd
    from msf_request_name_chg
   where cret_dt >= to_date(to_char(now(), 'YYYYMMDD'), 'YYYYMMDD')
     and cret_id = #{value}
), svcnl as (
  select proc_cd
    from msf_request_cancel
   where cret_dt >= to_date(to_char(now(), 'YYYYMMDD'), 'YYYYMMDD')
     and cret_id = #{value}
)

mapper.update:
update msf_board_bas
   set board_hit_cnt = coalesce(board_hit_cnt, 0) + 1
 where board_seq #{item}

update msf_qna_board_bas
   set board_hit_cnt = coalesce(board_hit_cnt, 0) + 1
 where qna_seq #{item}
